
/* =========================================
   VUDONG CLIENT - BLACK RED EDITION
   HAXBALL MOBILE
========================================= */

(() => {
"use strict";

const VERSION = "1.0.0";
const $ = (s, d = document) => d.querySelector(s);

const COLORS = {
  bg: "#101010",
  panel: "#191919",
  red: "#b91c1c",
  bright: "#ef4444",
  border: "#581b1b",
  white: "#ffffff"
};

const MAIN_CSS = `
body {
  background:${COLORS.bg} !important;
  color:white !important;
  user-select:none;
}
.dialog {
  background:${COLORS.panel} !important;
  border:1px solid ${COLORS.border} !important;
  border-radius:12px !important;
}
button {
  color:white !important;
  border-color:${COLORS.border} !important;
}
button:hover {
  border-color:${COLORS.bright} !important;
}
[data-hook="leave-btn"] {
  background:${COLORS.red} !important;
}
.game-view > .top-section,
.room-view {
  margin-top:0 !important;
}
.room-view,.roomlist-view {
  height:100%;
}
.game-state-view .scoreboard {
  color:white !important;
}
`;

const CONTROL_CSS = `
#joystick,#kick {
  position:absolute;
  z-index:100;
  bottom:5%;
  width:20%;
  aspect-ratio:1;
  opacity:1;
  border-radius:50%;
  touch-action:none;
}
#joystick {
  left:5%;
  background:#7f1d1d66;
  border:2px solid #b91c1c;
}
#thumb {
  position:absolute;
  width:40%;
  height:40%;
  left:30%;
  top:30%;
  border-radius:50%;
  background:#ef4444cc;
}
#kick {
  right:5%;
  background:#b91c1c;
  border:2px solid #ef4444;
  color:white;
  box-shadow:0 0 15px #b91c1c88;
}
#kick svg {
  width:50%;
  fill:white;
}
#vudong-panel {
  position:absolute;
  top:8px;
  right:8px;
  z-index:999;
  padding:7px 12px;
  background:#191919dd;
  border:1px solid #7f1d1d;
  border-radius:8px;
  color:white;
  font:bold 12px Arial;
}
`;

function injectStyle(doc, id, css) {
  if (!doc || !doc.head) return;
  let style = doc.getElementById(id);
  if (!style) {
    style = doc.createElement("style");
    style.id = id;
    doc.head.appendChild(style);
  }
  style.textContent = css;
}

function start() {
  const frame = $(".gameframe");
  if (!frame) {
    console.error("Vudong: Game frame not found.");
    return;
  }

  let game;
  try {
    game = frame.contentWindow;
    injectStyle(game.document, "vudong-theme", MAIN_CSS);
  } catch (e) {
    console.error("Vudong: Cannot access game frame.", e);
    return;
  }

  injectStyle(document, "vudong-controls-style", CONTROL_CSS);

  const body = game.document.body;
  if (!body) return;

  const get = hook => body.querySelector(
    `[data-hook="${hook}"]`
  );

  let joystick;
  let thumb;
  let kickButton;
  let touching = false;
  let previousKeys = "";
  let lastMessage = null;

  const stored = JSON.parse(
    localStorage.getItem("vudong-controls") || "null"
  );

  const settings = {
    size: stored?.size ?? 20,
    margin: stored?.margin ?? 5,
    opacity: stored?.opacity ?? 1
  };

  function applySettings() {
    if (!joystick || !kickButton) return;

    [joystick, kickButton].forEach(el => {
      el.style.width = settings.size + "%";
      el.style.bottom = settings.margin + "%";
      el.style.opacity = settings.opacity;
    });

    joystick.style.left = settings.margin + "%";
    kickButton.style.right = settings.margin + "%";

    localStorage.setItem(
      "vudong-controls",
      JSON.stringify(settings)
    );
  }

  function emulateKeys(keys) {
    if (keys === previousKeys) return;
    previousKeys = keys;

    const map = {
      w: "KeyW",
      a: "KeyA",
      s: "KeyS",
      d: "KeyD"
    };

    Object.entries(map).forEach(([key, code]) => {
      const type = keys.includes(key) ? "keydown" : "keyup";
      game.document.dispatchEvent(
        new KeyboardEvent(type, {
          code,
          key,
          bubbles: true
        })
      );
    });
  }

  function kick(down) {
    game.document.dispatchEvent(
      new KeyboardEvent(
        down ? "keydown" : "keyup",
        {
          code: "KeyX",
          key: "x",
          bubbles: true
        }
      )
    );
  }

  function resetJoystick() {
    if (!joystick || !thumb) return;

    thumb.style.left = "30%";
    thumb.style.top = "30%";
    emulateKeys("");
  }

  function updateJoystick(touch) {
    const rect = joystick.getBoundingClientRect();

    const dx = touch.clientX - (rect.left + rect.width / 2);
    const dy = touch.clientY - (rect.top + rect.height / 2);

    const angle = Math.atan2(dy, dx);
    const distance = Math.min(
      rect.width / 2,
      Math.hypot(dx, dy)
    );

    const x = rect.width / 2 +
      distance * Math.cos(angle) -
      thumb.offsetWidth / 2;

    const y = rect.height / 2 +
      distance * Math.sin(angle) -
      thumb.offsetHeight / 2;

    thumb.style.left = x + "px";
    thumb.style.top = y + "px";

    const sector = Math.round(
      ((angle * 180 / Math.PI + 360) % 360) / 45
    ) % 8;

    const directions = [
      "d", "sd", "s", "sa",
      "a", "wa", "w", "wd"
    ];

    emulateKeys(directions[sector]);
  }

  function createControls() {
    if (joystick) return;

    joystick = document.createElement("div");
    joystick.id = "joystick";
    joystick.innerHTML =
      '<div id="thumb"></div>';

    thumb = joystick.firstElementChild;

    kickButton = document.createElement("button");
    kickButton.id = "kick";
    kickButton.innerHTML = `
      <svg viewBox="0 0 512 512">
        <path d="M290 49c-16 0-32 14-38 36-6 25 5 48 22 52 18 5 39-10 45-35 7-25-5-48-22-52l-7-1zM89 68 78 87c32 16 63 34 96 47l28-12c-40-16-77-34-113-54zm148 56c-48 26-98 42-154 62l9 16c52-16 111-33 161-56-7-6-12-13-16-22zm30 35c-22 11-46 20-71 29-20 45-28 95-37 140l-2 11-101-40-16 26 130 60 3-4 15-29a1672 1672 0 0 0 79-193zm30 0"/>
      </svg>`;

    joystick.addEventListener("touchstart", e => {
      e.preventDefault();
      touching = true;
      updateJoystick(e.touches[0]);
    }, { passive: false });

    joystick.addEventListener("touchmove", e => {
      e.preventDefault();
      if (touching) updateJoystick(e.touches[0]);
    }, { passive: false });

    joystick.addEventListener("touchend", e => {
      e.preventDefault();
      touching = false;
      resetJoystick();
    });

    kickButton.addEventListener("touchstart", e => {
      e.preventDefault();
      kick(true);
    }, { passive: false });

    kickButton.addEventListener("touchend", e => {
      e.preventDefault();
      kick(false);
    });

    kickButton.addEventListener("touchcancel", () => kick(false));

    document.body.appendChild(joystick);
    document.body.appendChild(kickButton);

    applySettings();
  }

  function showControls(show) {
    if (!joystick || !kickButton) return;
    joystick.style.display = show ? "block" : "none";
    kickButton.style.display = show ? "block" : "none";
    if (!show) resetJoystick();
  }

  function createPanel() {
    if ($("#vudong-panel")) return;

    const panel = document.createElement("div");
    panel.id = "vudong-panel";
    panel.textContent = "VUDONG CLIENT v" + VERSION;
    document.body.appendChild(panel);
  }

  function updateChat() {
    const log = get("log");
    if (!log || !log.firstChild) return;

    const children = log.firstChild.children;
    if (log.firstChild.lastChild !== lastMessage) {
      if (children.length > 5) {
        for (let i = 0; i < children.length - 5; i++) {
          children[i].style.display = "none";
        }
      }

      lastMessage = log.firstChild.lastChild;
      if (lastMessage) {
        lastMessage.style.opacity = 1;
        setTimeout(() => {
          if (!lastMessage) return;
          lastMessage.classList.add("fade-out");
        }, 500);
      }
    }
  }

  function setupChat() {
    const chat = $(".chatbox-view", body);
    if (!chat || get("chat-toggle")) return;

    const button = game.document.createElement("button");
    button.dataset.hook = "chat-toggle";
    button.textContent = "CHAT";

    button.addEventListener("click", () => {
      const input = chat.querySelector(".input");
      if (!input) return;
      input.style.display =
        input.style.display === "none" ? "block" : "none";
      if (input.style.display === "block") {
        chat.querySelector("input")?.focus();
      }
    });

    body.querySelector(".sound-button-container")
      ?.parentNode?.prepend(button);
  }

  function updateUI() {
    const inGame =
      $(".game-view", body) &&
      !$(".room-view", body);

    if (inGame) {
      createControls();
      createPanel();
      setupChat();
      showControls(true);
    } else {
      showControls(false);
      $("#vudong-panel")?.remove();
    }

    updateChat();
  }

  const observer = new MutationObserver(updateUI);
  observer.observe(body, {
    childList: true,
    subtree: true
  });

  createControls();
  showControls(false);
  updateUI();

  console.log(
    "%cVUDONG CLIENT " + VERSION + " LOADED",
    "color:#ef4444;font-weight:bold"
  );
}

const loader = setInterval(() => {
  const frame = $(".gameframe");
  try {
    const doc = frame?.contentWindow?.document;
    if (
      doc?.body &&
      doc.querySelector(".choose-nickname-view")
    ) {
      clearInterval(loader);
      start();
    }
  } catch (e) {
    clearInterval(loader);
    console.error(e);
  }
}, 1000);

})();
      

